  return {
    seed,
    roadsV,
    roadsH,
    buildings,
    parks,
    trees,
    containers,
    piers,
    bank,
    vaultPos,
    safehousePos,
    cratePos,
    docksPos,
    pickups,
    startPos: { x: 1050, y: 1050 },
